class UserCard {
  private _avatar?: HTMLElement;
  constructor(private id: string, private host: HTMLElement) {}

  get avatar() {
    if (!this._avatar) this._avatar = this.host.querySelector(`#avatar-${this.id}`) as HTMLElement;
    return this._avatar;
  }
}

export class GridRow {
  private cellEl?: HTMLElement;
  constructor(private host: HTMLElement) {}

  get cell() {
    if (!this.cellEl) this.cellEl = this.host.querySelector('.cell') as HTMLElement;
    return this.cellEl;
  }
}

/* Version A: caches element lazily */
class TooltipA {
  private _el?: HTMLElement;
  constructor(private host: HTMLElement) {}
  get content() {
    if (!this._el) this._el = this.host.querySelector('.content') as HTMLElement;
    return this._el;
  }
}

/* Version B: resolves element on each access */
class TooltipB {
  constructor(private host: HTMLElement) {}
  get content() {
    return this.host.querySelector('.content') as HTMLElement | null;
  }
}
